public int maxEnvelopes(int[][] env) {
    Arrays.sort(env, (a, b) -> a[0] != b[0] ? a[0] - b[0] : b[1] - a[1]);
    int[] tails = new int[env.length];
    int size = 0;
    for (int[] e : env) {
        int x = e[1], lo = 0, hi = size;
        while (lo < hi) { int m = (lo + hi) >>> 1; if (tails[m] < x) lo = m + 1; else hi = m; }
        tails[lo] = x;
        if (lo == size) size++;
    }
    return size;
}

public int findNumberOfLIS(int[] nums) {
    int n = nums.length, maxLen = 0, result = 0;
    int[] len = new int[n], cnt = new int[n];
    for (int i = 0; i < n; i++) {
        len[i] = cnt[i] = 1;
        for (int j = 0; j < i; j++) if (nums[j] < nums[i]) {
            if (len[j] + 1 > len[i]) { len[i] = len[j] + 1; cnt[i] = cnt[j]; }
            else if (len[j] + 1 == len[i]) cnt[i] += cnt[j];
        }
        if (len[i] > maxLen) { maxLen = len[i]; result = cnt[i]; }
        else if (len[i] == maxLen) result += cnt[i];
    }
    return result;
}

public int maxHeight(int[][] cuboids) {
    for (int[] c : cuboids) Arrays.sort(c);
    Arrays.sort(cuboids, (a, b) ->
        a[0] != b[0] ? a[0] - b[0] : a[1] != b[1] ? a[1] - b[1] : a[2] - b[2]);
    int n = cuboids.length, ans = 0;
    int[] dp = new int[n];
    for (int i = 0; i < n; i++) {
        dp[i] = cuboids[i][2];
        for (int j = 0; j < i; j++)
            if (cuboids[j][0] <= cuboids[i][0] && cuboids[j][1] <= cuboids[i][1]
                    && cuboids[j][2] <= cuboids[i][2])
                dp[i] = Math.max(dp[i], dp[j] + cuboids[i][2]);
        ans = Math.max(ans, dp[i]);
    }
    return ans;
}

private int[][] memo;
private static final int[][] DIRS = {{0,1},{0,-1},{1,0},{-1,0}};

public int longestIncreasingPath(int[][] g) {
    int m = g.length, n = g[0].length, best = 0;
    memo = new int[m][n];
    for (int i = 0; i < m; i++)
        for (int j = 0; j < n; j++)
            best = Math.max(best, dfs(g, i, j));
    return best;
}
private int dfs(int[][] g, int i, int j) {
    if (memo[i][j] != 0) return memo[i][j];
    int best = 1;
    for (int[] d : DIRS) {
        int ni = i + d[0], nj = j + d[1];
        if (ni >= 0 && ni < g.length && nj >= 0 && nj < g[0].length && g[ni][nj] > g[i][j])
            best = Math.max(best, 1 + dfs(g, ni, nj));
    }
    return memo[i][j] = best;
}

public int makeArrayIncreasing(int[] arr1, int[] arr2) {
    int[] b = Arrays.stream(arr2).distinct().sorted().toArray();
    Map<Integer, Integer> dp = new HashMap<>();
    dp.put(-1, 0);
    for (int x : arr1) {
        Map<Integer, Integer> next = new HashMap<>();
        for (Map.Entry<Integer, Integer> e : dp.entrySet()) {
            int prev = e.getKey(), ops = e.getValue();
            if (x > prev)
                next.merge(x, ops, Math::min);
            int idx = upperBound(b, prev);
            if (idx < b.length)
                next.merge(b[idx], ops + 1, Math::min);
        }
        if (next.isEmpty()) return -1;
        dp = next;
    }
    int ans = Integer.MAX_VALUE;
    for (int v : dp.values()) ans = Math.min(ans, v);
    return ans;
}
private int upperBound(int[] a, int key) {
    int lo = 0, hi = a.length;
    while (lo < hi) { int m = (lo + hi) >>> 1; if (a[m] <= key) lo = m + 1; else hi = m; }
    return lo;
}

