private int maxProfit(int k, int[] prices) {
    int n = prices.length;
    if (n == 0 || k == 0) return 0;
    int[] buy = new int[k + 1], sell = new int[k + 1];
    Arrays.fill(buy, Integer.MIN_VALUE);
    for (int p : prices)
        for (int j = 1; j <= k; j++) {
            buy[j]  = Math.max(buy[j], sell[j - 1] - p);
            sell[j] = Math.max(sell[j], buy[j] + p);
        }
    return sell[k];
}

public int maxProfit(int k, int[] prices) {
    int n = prices.length;
    if (n == 0 || k == 0) return 0;
    if (k >= n / 2) {
        int profit = 0;
        for (int i = 1; i < n; i++)
            if (prices[i] > prices[i - 1]) profit += prices[i] - prices[i - 1];
        return profit;
    }
    int[] buy = new int[k + 1], sell = new int[k + 1];
    Arrays.fill(buy, Integer.MIN_VALUE);
    for (int p : prices)
        for (int j = 1; j <= k; j++) {
            buy[j]  = Math.max(buy[j], sell[j - 1] - p);
            sell[j] = Math.max(sell[j], buy[j] + p);
        }
    return sell[k];
}

public int maxProfit(int[] prices) {
    int hold = Integer.MIN_VALUE, sold = 0, rest = 0;
    for (int p : prices) {
        int prevSold = sold;
        sold = hold + p;
        hold = Math.max(hold, rest - p);
        rest = Math.max(rest, prevSold);
    }
    return Math.max(sold, rest);
}

public int maxProfit(int[] prices, int fee) {
    int cash = 0, hold = -prices[0];
    for (int i = 1; i < prices.length; i++) {
        cash = Math.max(cash, hold + prices[i] - fee);
        hold = Math.max(hold, cash - prices[i]);
    }
    return cash;
}

public boolean canPartitionKSubsets(int[] nums, int k) {
    int sum = 0;
    for (int x : nums) sum += x;
    if (sum % k != 0) return false;
    int target = sum / k, n = nums.length;
    Arrays.sort(nums);
    if (nums[n - 1] > target) return false;
    int[] dp = new int[1 << n];
    Arrays.fill(dp, -1);
    dp[0] = 0;
    for (int mask = 0; mask < (1 << n); mask++) {
        if (dp[mask] == -1) continue;
        for (int i = 0; i < n; i++) {
            if ((mask & (1 << i)) == 0 && dp[mask] + nums[i] <= target) {
                int next = mask | (1 << i);
                if (dp[next] == -1)
                    dp[next] = (dp[mask] + nums[i]) % target;
            }
        }
    }
    return dp[(1 << n) - 1] == 0;
}

public int shortestPathLength(int[][] graph) {
    int n = graph.length;
    if (n == 1) return 0;
    int full = (1 << n) - 1;
    boolean[][] visited = new boolean[n][1 << n];
    Deque<int[]> queue = new ArrayDeque<>();
    for (int i = 0; i < n; i++) {
        queue.offer(new int[]{i, 1 << i});
        visited[i][1 << i] = true;
    }
    int steps = 0;
    while (!queue.isEmpty()) {
        int size = queue.size();
        for (int s = 0; s < size; s++) {
            int[] cur = queue.poll();
            int node = cur[0], mask = cur[1];
            if (mask == full) return steps;
            for (int next : graph[node]) {
                int nmask = mask | (1 << next);
                if (!visited[next][nmask]) {
                    visited[next][nmask] = true;
                    queue.offer(new int[]{next, nmask});
                }
            }
        }
        steps++;
    }
    return -1;
}

public int connectTwoGroups(List<List<Integer>> cost) {
    int m = cost.size(), n = cost.get(0).size();
    int[] minConnect = new int[n];
    Arrays.fill(minConnect, Integer.MAX_VALUE);
    for (int i = 0; i < m; i++)
        for (int j = 0; j < n; j++)
            minConnect[j] = Math.min(minConnect[j], cost.get(i).get(j));
    Integer[][] memo = new Integer[m][1 << n];
    return dfs(0, 0, cost, minConnect, memo, m, n);
}
private int dfs(int i, int mask, List<List<Integer>> cost, int[] minConnect,
                Integer[][] memo, int m, int n) {
    if (i == m) {
        int total = 0;
        for (int j = 0; j < n; j++)
            if ((mask & (1 << j)) == 0) total += minConnect[j];
        return total;
    }
    if (memo[i][mask] != null) return memo[i][mask];
    int best = Integer.MAX_VALUE;
    for (int j = 0; j < n; j++) {
        int c = cost.get(i).get(j) + dfs(i + 1, mask | (1 << j), cost, minConnect, memo, m, n);
        best = Math.min(best, c);
    }
    return memo[i][mask] = best;
}

public String shortestSuperstring(String[] words) {
    int n = words.length;
    int[][] overlap = new int[n][n];
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if (i != j) overlap[i][j] = calcOverlap(words[i], words[j]);
    int[][] dp = new int[1 << n][n];
    int[][] parent = new int[1 << n][n];
    for (int[] row : parent) Arrays.fill(row, -1);
    for (int mask = 1; mask < (1 << n); mask++)
        for (int i = 0; i < n; i++) {
            if ((mask & (1 << i)) == 0) continue;
            int prevMask = mask ^ (1 << i);
            if (prevMask == 0) continue;
            for (int j = 0; j < n; j++) {
                if ((prevMask & (1 << j)) == 0) continue;
                int val = dp[prevMask][j] + overlap[j][i];
                if (val > dp[mask][i]) {
                    dp[mask][i] = val;
                    parent[mask][i] = j;
                }
            }
        }
    int full = (1 << n) - 1, last = 0, best = -1;
    for (int i = 0; i < n; i++)
        if (dp[full][i] > best) { best = dp[full][i]; last = i; }
    List<Integer> order = new ArrayList<>();
    int mask = full, cur = last;
    while (cur != -1) {
        order.add(cur);
        int p = parent[mask][cur];
        mask ^= (1 << cur);
        cur = p;
    }
    Collections.reverse(order);
    StringBuilder sb = new StringBuilder(words[order.get(0)]);
    for (int k = 1; k < order.size(); k++) {
        int ov = overlap[order.get(k - 1)][order.get(k)];
        sb.append(words[order.get(k)].substring(ov));
    }
    return sb.toString();
}
private int calcOverlap(String a, String b) {
    int max = Math.min(a.length(), b.length());
    for (int len = max; len > 0; len--)
        if (a.regionMatches(a.length() - len, b, 0, len)) return len;
    return 0;
}

public int maxStudents(char[][] seats) {
    int m = seats.length, n = seats[0].length;
    int[] valid = new int[m];
    for (int i = 0; i < m; i++)
        for (int j = 0; j < n; j++)
            if (seats[i][j] == '.') valid[i] |= (1 << j);
    int[] prev = new int[1 << n];
    Arrays.fill(prev, -1);
    prev[0] = 0;
    for (int i = 0; i < m; i++) {
        int[] cur = new int[1 << n];
        Arrays.fill(cur, -1);
        for (int mask = 0; mask < (1 << n); mask++) {
            if ((mask & valid[i]) != mask) continue;
            if ((mask & (mask << 1)) != 0) continue;
            for (int pmask = 0; pmask < (1 << n); pmask++) {
                if (prev[pmask] == -1) continue;
                if ((mask & (pmask << 1)) != 0) continue;
                if ((mask & (pmask >> 1)) != 0) continue;
                cur[mask] = Math.max(cur[mask], prev[pmask] + Integer.bitCount(mask));
            }
        }
        prev = cur;
    }
    int ans = 0;
    for (int v : prev) ans = Math.max(ans, v);
    return ans;
}

public int numberWays(List<List<Integer>> hats) {
    final int MOD = 1_000_000_007;
    int n = hats.size();
    List<List<Integer>> hatToPeople = new ArrayList<>();
    for (int h = 0; h <= 40; h++) hatToPeople.add(new ArrayList<>());
    for (int p = 0; p < n; p++)
        for (int h : hats.get(p))
            hatToPeople.get(h).add(p);
    int full = (1 << n) - 1;
    long[] dp = new long[1 << n];
    dp[0] = 1;
    for (int h = 1; h <= 40; h++) {
        long[] next = dp.clone();
        for (int mask = 0; mask <= full; mask++) {
            if (dp[mask] == 0) continue;
            for (int p : hatToPeople.get(h)) {
                if ((mask & (1 << p)) != 0) continue;
                int nmask = mask | (1 << p);
                next[nmask] = (next[nmask] + dp[mask]) % MOD;
            }
        }
        dp = next;
    }
    return (int) dp[full];
}
